from __future__ import annotations

import sys
from typing import Optional, TextIO

def format_value(value: Value) -> str:
    if value is None:
        return 'NULL'
    elif value is True:
        return 'TRUE'
    elif value is False:
        return 'FALSE'
    else:
        return str(value)

def format_result(result: QueryResult) -> str:
    if result.columns:
        headers = result.columns
        rows = result.rows
        max_widths = [max(len(format_value(cell)) for cell in column) for column in zip(*rows, headers)]
        header_line = ' | '.join(header.ljust(width) for header, width in zip(headers, max_widths))
        separator_line = ' | '.join('-' * width for width in max_widths)
        data_lines = [
            ' | '.join(format_value(cell).ljust(width) for cell, width in zip(row, max_widths))
            for row in rows
        ]
        row_count_line = f'(1 row)' if result.row_count == 1 else f'({result.row_count} rows)'
        return '\n'.join([header_line, separator_line] + data_lines + [row_count_line])
    else:
        return f'OK ({result.row_count} rows affected)'

def run_repl(
    stdin: TextIO,
    stdout: TextIO,
    stderr: TextIO,
    engine: Optional[Engine] = None,
) -> int:
    if engine is None:
        engine = Engine()
    buffer = ''
    while True:
        try:
            line = stdin.readline()
            if not line:
                break
            buffer += line
            if buffer.strip().endswith(';'):
                sql = buffer.strip().rstrip(';')
                if sql:
                    result = engine.execute(sql)
                    stdout.write(format_result(result) + '\n')
                buffer = ''
        except MiniDBError as e:
            stderr.write(f'ERROR: {str(e)}\n')
            buffer = ''
        except EOFError:
            break
    if buffer.strip():
        try:
            result = engine.execute(buffer.strip())
            stdout.write(format_result(result) + '\n')
        except MiniDBError as e:
            stderr.write(f'ERROR: {str(e)}\n')
    return 0

def main(argv: Optional[list[str]] = None) -> int:
    return run_repl(sys.stdin, sys.stdout, sys.stderr)

if __name__ == "__main__":
    sys.exit(main())

